mapper.select:
SELECT
(select scv.MEANING from sys_code_b sc, sys_code_value_b scv where sc.CODE_ID = scv.CODE_ID and sc.CODE = 'SYS.YES_NO' and scv.value = hlid.if_pledge) if_pledge_n, (select scv.MEANING from sys_code_b sc, sys_code_value_b scv where sc.CODE_ID = scv.CODE_ID and sc.CODE = 'SYS.YES_NO' and scv.value = hlid.if_insure) if_insure_n, (select scv.MEANING from sys_code_b sc, sys_code_value_b scv where sc.CODE_ID = scv.CODE_ID and sc.CODE = 'SYS.YES_NO' and scv.value = hlid.if_reduce_exempt_tax) if_reduce_exempt_tax_n,
hlid.* FROM hls_lease_item_detail hlid,hls_lease_item hli,prj_project_lease_item pp
1 = 1 and hli.asset_types = hlid.asset_types and hli.lease_item_id = hlid.lease_item_id and hli.lease_item_id = pp.lease_item_id
and hlid.lease_item_id = #{leaseItemId}
and pp.project_id = #{projectId}

SELECT
hlid.*
FROM hls_lease_item_detail hlid

    1 = 1

        and hlid.lease_item_id = #{leaseItemId}


        and hlid.serial_number = #{serialNumber}

select t1.* from hls_lease_item_detail t1,hls_lease_item t2 where t1.PATTERN_DET = 'MOVABLE_PROPERTY_PLEDGE'
and t1.lease_item_id = #{leaseItemId}
and t1.lease_item_id = t2.lease_item_id order by t1.lease_item_detail_id desc

select t1.* from hls_lease_item_detail t1,hls_lease_item t2 where t1.PATTERN_DET = 'NO_MOVABLE_PROPERTY_PLEDGE'
and t1.lease_item_id = #{leaseItemId}
and t1.lease_item_id = t2.lease_item_id order by t1.lease_item_detail_id desc

select t1.* from hls_lease_item_detail t1,hls_lease_item t2 where t1.PATTERN_DET = 'DZ_PROPERTY_PLEDGE'
and t1.lease_item_id = #{leaseItemId}
and t1.lease_item_id = t2.lease_item_id order by t1.lease_item_detail_id desc

SELECT t1.*, hli.LEASE_ITEM_CODE, ( SELECT wm_concat(p.project_number) FROM prj_project_chance_mp pi, prj_project p WHERE pi.project_id = p.project_id AND pi.lease_item_id = hli.lease_item_id and p.data_class = 'NORMAL' ) AS project_number, ( SELECT wm_concat(p.contract_number) FROM prj_project_chance_mp pi, prj_project p WHERE pi.project_id = p.project_id AND pi.lease_item_id = hli.lease_item_id AND p.data_class = 'VIRTUAL_CON' ) AS contract_number, hli.FULL_NAME, ( SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'HLS.COLLATERAL_TYPE' AND code_value = hli.LEASE_ITEM_TYPE ) AS LEASE_ITEM_TYPE_N, hli.PATTERN, ( SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'HLS.PATTERN' AND code_value = hli.PATTERN ) AS PATTERN_N, hbm.bp_name AS MORTGAGOR_N, ( SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'PLEDGE_STATE0' AND code_value = hli.PLEDGE_STATE ) AS PLEDGE_STATE_N, a.EVALUATION_VALUE AS ASSET_VALUE_TOTAL, b.original_asset_value_total FROM hls_lease_item hli LEFT JOIN hls_lease_item_detail t1 ON t1.lease_item_id = hli.lease_item_id AND t1.PATTERN_DET = 'DZ_PROPERTY_PLEDGE' LEFT JOIN hls_bp_master hbm ON hbm.bp_id = hli.MORTGAGOR LEFT JOIN ( SELECT hlid.lease_item_id, SUM( hlid.EVALUATION_VALUE ) AS EVALUATION_VALUE FROM hls_lease_item_detail hlid GROUP BY hlid.lease_item_id ) a ON a.lease_item_id = hli.lease_item_id LEFT JOIN ( SELECT hlid.lease_item_id, SUM( nvl(hlid.purchase_price,0) + nvl(hlid.pledge_asset_value,0)) AS original_asset_value_total FROM hls_lease_item_detail hlid GROUP BY hlid.lease_item_id ) b ON b.lease_item_id = hli.lease_item_id where hli.pattern IN ( 'GUQUAN_PROPERTY_PLEDGE', 'SHOUKUAN_PROPERTY_PLEDGE', 'SHOUYIQUAN_PROPERTY_PLEDGE' )
and t1.lease_item_id = #{leaseItemId}
and hli.lease_item_code like concat(concat('%',#{leaseItemCode}),'%')
and hli.full_name like concat(concat('%',#{fullName}),'%')
and hli.pattern = #{pattern}
order by hli.lease_item_id desc
